INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('pflegende-angehoerige-volkshilfe-fonds-1000-euro-2026','Pflegende Angehörige: Volkshilfe-Fonds zahlt bis zu 1.000 Euro im Jahr','Pflegende Angehörige, die von Armut betroffen sind, können beim Fonds „Pflege möglich machen“ der Volkshilfe einmal im Jahr bis zu 1.000 Euro beantragen – etwa für Hilfsmittel, Therapien oder Ersatzpflege.','Pflegende Angehörige mit geringem Einkommen können bei der Volkshilfe Österreich einmal pro Jahr bis zu 1.000 Euro Unterstützung beantragen. Die Hilfsorganisation hat ihren Fonds „Pflege möglich machen“ anlässlich des Internationalen Tags der Betreuung und Unterstützung am 29. Oktober vorgestellt. Gedacht ist das Geld für Familien, in denen ein Mensch zu Hause gepflegt wird und das Haushaltsbudget nicht ausreicht.

## Pflegende Angehörige tragen die Hauptlast

Laut Volkshilfe kümmern sich in Österreich rund 950.000 Angehörige täglich um einen pflegebedürftigen Menschen. Mehr als zwei Drittel davon sind Frauen. Die Pflege daheim ist damit nach wie vor die tragende Säule des Systems – und für viele Familien eine finanzielle Belastung, weil Therapien, Hilfsmittel oder Selbstbehalte schnell ins Geld gehen.

Volkshilfe-Direktor Erich Fenninger betont, dass Anerkennung allein nicht reiche: „Pflegende Angehörige leisten Enormes.“ Es brauche konkrete, rasch wirksame Hilfe. Der Fonds ist eine Initiative der Volkshilfe selbst und keine staatliche Förderung.

## Wofür es Geld gibt

Die Unterstützung deckt ein breites Spektrum an Ausgaben ab, die bei der Pflege zu Hause anfallen. Dazu zählen laut Volkshilfe unter anderem:

- Pflegeprodukte und Hilfsmittel
- Ergotherapie, Physiotherapie, Logopädie und Psychotherapie
- Selbstbehalte für mobile Pflegedienste
- Haushaltshilfe und Alltagsbegleitung
- 24-Stunden-Betreuung
- Ersatzpflege, wenn die pflegende Person auf Urlaub fährt
- Tageszentren inklusive Fahrtkosten
- medizinische Leistungen und Essen auf Rädern

Auch bauliche Anpassungen werden berücksichtigt, etwa ein Treppenlift, ein Patientenlifter, ein Elektrorollstuhl oder ein barrierefreier Umbau. In diesen Fällen kann bereits ein Kostenvoranschlag eingereicht werden. Nicht gefördert werden Leistungen in stationären Einrichtungen wie Pflegeheimen.

## Welche Unterlagen nötig sind

Für den Antrag verlangt die Volkshilfe drei Arten von Nachweisen:

1. einen Einkommensnachweis,
2. den aktuellen Pflegegeldbescheid oder einen Beleg, dass ein Antrag auf Pflegegeld bereits läuft,
3. gegebenenfalls Rechnungen über die angefallenen Kosten.

Die Formulare stehen auf der Website der Volkshilfe zum Download bereit. Eingereicht wird per E-Mail oder per Post. Wird der Antrag bewilligt, überweist die Organisation das Geld nach eigenen Angaben innerhalb eines Monats.

## Was noch offen ist

Konkrete Einkommensgrenzen oder eine Einreichfrist nennt die Aussendung nicht. Angesprochen sind ausdrücklich Pflegebedürftige und ihre Familien, die armutsgefährdet oder armutsbetroffen sind. Wer unsicher ist, ob er in Frage kommt, sollte sich direkt bei der Volkshilfe erkundigen, bevor er Rechnungen sammelt.

Teresa Millner-Kurzbauer, Leiterin des Bereichs Pflege bei der Volkshilfe Österreich, verweist darauf, dass die Hilfe einmal jährlich gewährt werden kann und schnell bei den Betroffenen ankommen müsse.

## Weitere Anlaufstellen

Der Volkshilfe-Fonds ersetzt keine öffentlichen Leistungen. Grundlage bleibt das Pflegegeld, das je nach Pflegebedarf in sieben Stufen ausbezahlt wird. Daneben gibt es Zuschüsse des Sozialministeriumservice, etwa für die 24-Stunden-Betreuung oder für Ersatzpflege, sowie Angebote der Bundesländer. Der neue Fonds kann eine Lücke schließen, wenn diese Leistungen nicht reichen oder Kosten anfallen, die anderswo nicht gedeckt sind. Wer noch kein Pflegegeld bezieht, sollte den Antrag beim zuständigen Pensionsversicherungsträger möglichst früh stellen – auch weil ein laufendes Verfahren für die Einreichung beim Volkshilfe-Fonds bereits ausreicht.','gesundheit','Pflege',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/pflegende-angehoerige-volkshilfe-fonds-1000-euro-2026.webp','Volkshilfe Österreich (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261029_OTS0075/zum-internationalen-tag-der-betreuung-und-unterstuetzung-neuer-pflegefonds-entlastet-pflegende-angehoerige-mit-bis-zu-1000-euro-pro-jahr','published','2026-10-31T11:55:00.000Z','2026-11-01T11:53:57.123Z','Pflegende Angehörige: Bis zu 1.000 € von der Volkshilfe','Pflegende Angehörige mit wenig Geld können bei der Volkshilfe bis zu 1.000 Euro pro Jahr beantragen. Wofür es Geld gibt und welche Unterlagen nötig sind.','Pflegende Angehörige','["Pflegende Angehörige","Volkshilfe Pflegefonds","Pflege möglich machen","Unterstützung pflegende Angehörige Österreich","Pflege zu Hause Kosten","Zuschuss 24-Stunden-Betreuung","Treppenlift Zuschuss","Ersatzpflege Urlaub","Pflegegeld Antrag"]','Pflegende Angehörige: Eine Angehörige betreut eine ältere Person zu Hause im Wohnzimmer','Photorealistic scene in a modest Austrian apartment living room in autumn: an older person seated in an armchair with a walking frame beside it, a middle-aged relative kneeling and adjusting a blanket, seen from behind and side so faces are not visible, warm lamp light, wooden furniture, window with soft grey daylight, no text, no logos, no readable signs','[{"q":"Wie viel Geld bekommen pflegende Angehörige aus dem Volkshilfe-Fonds?","a":"Bis zu 1.000 Euro pro Jahr, die Unterstützung kann einmal jährlich gewährt werden."},{"q":"Wer kann beim Fonds „Pflege möglich machen“ einreichen?","a":"Pflegebedürftige Menschen und ihre Angehörigen, die zu Hause pflegen und armutsgefährdet oder armutsbetroffen sind."},{"q":"Welche Unterlagen braucht man für den Antrag?","a":"Einen Einkommensnachweis, den Pflegegeldbescheid oder den Nachweis eines laufenden Antrags sowie gegebenenfalls Rechnungen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
